insert into public.lesson_templates(id,kind,public_payload,provenance) values
 ('vocabulary-original-v1','vocabulary','{"prompt":"Choose the word that means possible to continue over time: A. sustainable B. sudden C. empty","choices":["sustainable","sudden","empty"],"available":true}','{"author":"Boji project original content","sourceUrl":null,"license":"Project license decision pending","verifiedAt":"2026-10-15"}'),
 ('reading-original-v1','reading','{"passage":"Mira used to plan an hour of study every evening. Most evenings she was too tired to begin. She changed her plan to ten focused minutes after breakfast and kept a notebook of questions. After two weeks, she had studied on twelve days. Her goal was still ambitious, but her daily step had become easier to repeat.","prompt":"What mainly helped Mira study regularly? A. A smaller repeatable step B. A harder exam C. A longer evening session","choices":["A smaller repeatable step","A harder exam","A longer evening session"],"available":true}','{"author":"Boji project original content","sourceUrl":null,"license":"Project license decision pending","verifiedAt":"2026-10-15"}'),
 ('listening-original-v1','listening','{"prompt":"Listen to the club announcement and identify the opening time.","available":false,"unavailableReason":"An original licensed audio rendition has not been provisioned. This is a system limitation, not a failed answer."}','{"author":"Boji project original script","sourceUrl":null,"license":"Audio not provisioned","verifiedAt":"2026-10-15"}'),
 ('writing-original-v1','writing','{"prompt":"Write a short paragraph about a small habit you can repeat this week. Explain why it is realistic and give one concrete example.","targetWords":80,"rubric":["content","organization","grammar","vocabulary"],"available":true}','{"author":"Boji project original content","sourceUrl":null,"license":"Project license decision pending","verifiedAt":"2026-10-15"}'),
 ('speaking-original-v1','speaking','{"prompt":"Describe a place where you like to learn. Explain what makes it useful for you.","available":true,"assessmentStatus":"unavailable","notice":"Verified audio processing is not configured. A transcript is not pronunciation evidence."}','{"author":"Boji project original content","sourceUrl":null,"license":"Project license decision pending","verifiedAt":"2026-10-15"}')
insert into public.template_private_keys(template_id,private_payload) values
 ('vocabulary-original-v1','{"accepted":["sustainable","A"],"explanation":"Sustainable describes a practice that can continue over time.","evidence":"possible to continue over time"}'),
 ('reading-original-v1','{"accepted":["A","A smaller repeatable step","a smaller daily step"],"explanation":"Mira made the daily task smaller and easier to repeat.","evidence":"her daily step had become easier to repeat"}'),
 ('listening-original-v1','{"accepted":["7 am","7:00 am","seven in the morning"],"explanation":"The original announcement states the opening time.","evidence":"The club opens at seven in the morning.","transcript":"Welcome to the club. The club opens at seven in the morning. Please bring a notebook and choose a comfortable place to practice."}'),
 ('writing-original-v1','{"model":"This week I will read for ten minutes after breakfast. A short session fits my morning routine, so I can repeat it even when the day is busy. For example, I will read one short article and write down a question about it. My aim is to build a steady habit, not finish a whole book immediately."}'),
 ('speaking-original-v1','{"example":"I like learning at the small desk near my window because it is quiet. I keep my notebook there so that starting a short practice session is easy."}')
